import Link from 'next/link';
import { BookOpen, PlayCircle, Microphone, SignIn } from '@phosphor-icons/react/dist/ssr';
import {
  getCurrentUser,
  getProgress,
  getLatestVoiceProfile,
  getSubjects,
  type Subject,
} from '@/lib/api';
import { Container, Card, btnPrimary, PageHeader } from '@/components/ui';
import RangeTestPanel from '@/components/RangeTestPanel';
import { getRequestDictionary } from '@/lib/i18n-server';
import type { Dictionary } from '@/lib/i18n';

// Personalized to the signed-in session, so never cache.
export const dynamic = 'force-dynamic';

type FlatLesson = {
  id: string;
  title: string;
  durationMin: number;
  subjectName: string;
  lectureTitle: string;
};

function flattenLessons(subjects: Subject[]): FlatLesson[] {
  return subjects.flatMap((subject) =>
    subject.lectures.flatMap((lecture) =>
      lecture.lessons.map((lesson) => ({
        id: lesson.id,
        title: lesson.title,
        durationMin: lesson.durationMin,
        subjectName: subject.name,
        lectureTitle: lecture.title,
      }))
    )
  );
}

export default async function DashboardPage() {
  const { locale, dictionary } = await getRequestDictionary();
  const user = await getCurrentUser();

  if (!user) {
    return <SignedOutHome dictionary={dictionary} />;
  }

  const [progress, profile, subjects] = await Promise.all([
    getProgress(),
    getLatestVoiceProfile(),
    getSubjects(locale),
  ]);

  if (!profile) {
    // Show Range Test if the user has no voice profile
    return (
      <>
        <PageHeader
          eyebrow={dictionary.rangeTest.eyebrow}
          title={dictionary.rangeTest.title}
          lead={dictionary.rangeTest.lead}
        />
        <Container className="py-16">
          <RangeTestPanel />
        </Container>
      </>
    );
  }

  // Curriculum View
  const completedIds = new Set(
    progress.filter((p) => p.status === 'completed' && p.lessonId).map((p) => p.lessonId as string)
  );

  const allLessons = flattenLessons(subjects);
  const nextLesson = allLessons.find((lesson) => !completedIds.has(lesson.id)) ?? allLessons[0] ?? null;

  return (
    <Container className="py-16 max-w-4xl">
      <div className="mb-10 text-center">
        <p className="mb-2 text-xs font-semibold uppercase text-accent">
          {dictionary.home.dashboard}
        </p>
        <h1 className="text-3xl font-extrabold md:text-4xl">
          {dictionary.home.welcomeBack}{user.displayName ? `, ${user.displayName}` : ''}
        </h1>
        <p className="mt-4 text-muted max-w-2xl mx-auto">
          Based on your {profile.voiceType} profile ({profile.lowestNote} to {profile.highestNote}), here is your customized learning path.
        </p>
      </div>

      <div className="grid gap-6">
        {allLessons.map((lesson, idx) => {
          const isCompleted = completedIds.has(lesson.id);
          const isNext = nextLesson?.id === lesson.id;

          return (
            <Card
              key={lesson.id}
              className={`flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 transition ${
                isNext ? 'ring-2 ring-accent' : ''
              } ${isCompleted ? 'opacity-70' : ''}`}
            >
              <div>
                <p className="text-xs font-semibold uppercase text-faint">
                  {idx + 1}. {lesson.subjectName} · {lesson.lectureTitle}
                </p>
                <h2 className="mt-1 text-xl font-bold">{lesson.title}</h2>
                <p className="mt-1 flex items-center gap-1.5 text-sm text-muted">
                  <BookOpen size={16} aria-hidden /> {lesson.durationMin} {dictionary.common.minutes}
                  {isCompleted && (
                    <span className="ml-2 inline-flex items-center gap-1 text-accent font-medium">
                      ✓ Completed
                    </span>
                  )}
                </p>
              </div>
              <Link
                href={`/lessons/${lesson.id}`}
                className={isNext ? btnPrimary : 'rounded-full bg-white/10 px-6 py-2.5 text-sm font-semibold text-text transition hover:bg-white/20 inline-flex gap-2 items-center'}
              >
                <PlayCircle size={18} aria-hidden />
                {isCompleted ? 'Review' : isNext ? 'Start Lesson' : 'View'}
              </Link>
            </Card>
          );
        })}

        {allLessons.length === 0 && (
          <div className="text-center text-muted p-10 border border-white/10 rounded-2xl">
            {dictionary.home.lessonsLoading}
          </div>
        )}
      </div>
    </Container>
  );
}

function SignedOutHome({ dictionary }: { dictionary: Dictionary }) {
  return (
    <section className="relative overflow-hidden">
      <div
        aria-hidden
        className="pointer-events-none absolute -top-40 left-1/2 h-[520px] w-[680px] -translate-x-1/3 rounded-full"
        style={{
          background: 'radial-gradient(closest-side, rgba(255,184,77,0.18), transparent 72%)',
        }}
      />
      <Container className="relative py-20 md:py-28">
        <div className="max-w-xl text-center mx-auto">
          <p className="mb-3 text-xs font-semibold uppercase text-accent">
            {dictionary.home.signedOutEyebrow}
          </p>
          <h1 className="text-4xl font-extrabold md:text-5xl">{dictionary.home.signedOutTitle}</h1>
          <p className="mt-5 text-lg text-muted">
            {dictionary.home.signedOutLead}
          </p>
          <div className="mt-8 flex justify-center gap-3">
            <Link href="/account" className={btnPrimary}>
              <SignIn size={18} aria-hidden /> {dictionary.home.signIn}
            </Link>
          </div>
        </div>
      </Container>
    </section>
  );
}
